from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = set()

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if (0 <= ny < h and 0 <= nx < w and
                        (ny,nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny,nx))
                        stack.append((ny,nx))
            if len(comp) > 1:
                continue

            y, x = comp[0]
            # A stray pixel inside a solid patch is a damaged patch cell;
            # otherwise it is noise and becomes the background.
            replacement = bg
            for candidate in set(grid[yy][xx]
                                 for yy in range(max(0,y-2), min(h,y+3))
                                 for xx in range(max(0,x-2), min(w,x+3))
                                 if grid[yy][xx] != bg):
                if candidate == color:
                    continue
                horizontal = (x > 0 and grid[y][x-1] == candidate and
                              x+1 < w and grid[y][x+1] == candidate)
                vertical = (y > 0 and grid[y-1][x] == candidate and
                            y+1 < h and grid[y+1][x] == candidate)
                diagonal = sum(0 <= y+dy < h and 0 <= x+dx < w and
                               grid[y+dy][x+dx] == candidate
                               for dy, dx in ((-1,-1),(-1,1),(1,-1),(1,1)))
                if horizontal or vertical or diagonal >= 3:
                    replacement = candidate
                    break
            out[y][x] = replacement
    return out
